const fs = require('node:fs'), cp = require('node:child_process'), assert = require('node:assert/strict');
const {chromium} = require('<PLAYWRIGHT_MODULE>');
const root = '<EASYSTUD_SOURCE_ROOT>';
const runId = 'codex1-k1680-tail-f25o-native', out = __dirname;
const ps = (file, args) => cp.execFileSync('powershell.exe', ['-NoProfile', '-File', '<ORCHESTRATION_SCRIPTS>/' + file, ...args], {encoding: 'utf8'});
const css = file => fs.readFileSync(file, 'utf8').replace(/url\((["']?)(\.\.?\/[^)"']+)\1\)/g,
    (match, quote, relative) => 'url("' + new URL(relative, 'http://localhost:8051/local/groupimport/styles/student-management.css').href + '")');
async function settle(locator) {
    await locator.evaluate(async node => {
        const animations = [...node.getAnimations({subtree:true})];
        for (let n = node; n; n = n.parentElement) animations.push(...n.getAnimations());
        await Promise.all(animations.filter(a => Number.isFinite(a.effect.getTiming().iterations)).map(a => a.finished.catch(() => {})));
    });
}
async function measure(locator){return locator.evaluate(n=>{const m=n=>{const r=n.getBoundingClientRect(),s=getComputedStyle(n);return {width:r.width,height:r.height,padding:s.padding,radius:s.borderRadius,color:s.color,background:s.backgroundColor,border:s.border,shadow:s.boxShadow,outline:s.outline,fontSize:s.fontSize,lineHeight:s.lineHeight,focusVisible:n.matches(':focus-visible')};};const parts=[...document.querySelectorAll('.local-groupimport-admin-settings__page-identity,.local-groupimport-admin-settings__field-card h4')].filter(n=>n.getClientRects().length).map(n=>({class:n.className,tag:n.tagName,...m(n)}));if(!parts.some(p=>p.tag==='H4')||!parts.some(p=>p.class.includes('__page-identity')))throw Error('Actual native identity and field heading required');return {...m(n),parts};});}


(async () => {
    const result = {passed: false, rows: [], errors: [], runtimeFilesChanged: false};
    let lease = false, created = false, browser, page;
    try {
        ps('Acquire-EasyEduResourceLease.ps1', ['-Resource', 'moodle51-perf', '-ProjectNamespace', 'easystud', '-RunId', runId,
            '-Repository', root, '-Purpose', 'K16-80 disclosures exact native CSS parity, restored synthetic fixture', '-LeaseSeconds', '900', '-OwnerPid', String(process.pid)]);
        lease = true;
        const fixture = JSON.parse(cp.execFileSync('<PHP_BINARY>', [out + '/fixture.php', 'create'], {encoding: 'utf8'}));
        created = true; result.course = fixture.courseid;
        browser = await chromium.launch({headless: true, executablePath: '<CHROME_EXECUTABLE>'});
        for (const locale of ['fr', 'en']) for (const width of [1600, 390]) {
            const context = await browser.newContext({storageState: '<PROCESS_LOCAL_AUTH_STATE>',
                viewport: {width, height: 1000}, hasTouch: width === 390, reducedMotion: 'reduce'});
            page = await context.newPage();
            page.setDefaultTimeout(20000);
            page.on('pageerror', e => result.errors.push(e.message));
            page.on('console', m => {if (m.type() === 'error') result.errors.push(m.text());});
            const response = await page.goto('http://localhost:8051/admin/settings.php?section=local_groupimport&fixture=' + fixture.courseid + '&lang=' + locale,
                {waitUntil: 'domcontentloaded', timeout: 180000});
            assert.equal(response.status(), 200);
            await page.waitForFunction(()=>!document.body.classList.contains('local-groupimport-admin-settings-page--loading'),null,{timeout:180000});
            await page.evaluate(()=>document.querySelectorAll('link[rel="stylesheet"]').forEach(n=>{if(/\/local\/groupimport\/styles\//.test(n.href))n.disabled=true;}));
            const style=await page.addStyleTag({content:css(out+'/before-administration.css')});await page.evaluate(()=>document.fonts.ready);
            const control=page.locator('#adminsettings > .settingsform > .row:last-child button[type="submit"],#adminsettings > .settingsform > .row:last-child input[type="submit"]').first();await control.waitFor();await control.scrollIntoViewIfNeeded();
            for(const state of ['rest','focus-visible']){
                if(state==='focus-visible')await control.focus();else await control.evaluate(n=>n.blur());
                for(const phase of ['before','after']){
                    await style.evaluate((n,value)=>{n.textContent=value;},css(phase==='before'?out+'/before-administration.css':root+'/styles/administration.css'));await settle(control);
                    result.rows.push({kind:'native-admin-footer',locale,width,state,phase,measurement:await measure(control)});
                }
            }
            await context.close();
        }
        assert.equal(result.rows.length,16);
        for(const after of result.rows.filter(r=>r.phase==='after')){const before=result.rows.find(r=>r.phase==='before'&&r.locale===after.locale&&r.width===after.width&&r.state===after.state);assert.deepEqual(after.measurement,before.measurement,'Native admin frames and focus paint exactly unchanged');assert.equal(after.measurement.focusVisible,after.state==='focus-visible');}
        assert.equal(result.errors.length, 0); result.passed = true;
    } catch (e) {
        result.failure = e.message;
        if (page && !page.isClosed()) await page.screenshot({path: out + '/failure.png', timeout: 10000}).catch(() => {});
    } finally {
        if (browser) await browser.close();
        if (!created && fs.existsSync(out + '/fixture-ids.json')) {
            const ids = JSON.parse(fs.readFileSync(out + '/fixture-ids.json'));
            const restored = fs.existsSync(out + '/fixture-restored.json') ? JSON.parse(fs.readFileSync(out + '/fixture-restored.json')) : {};
            created = !(restored.removed && restored.courseid === ids.courseid);
        }
        if (created) result.fixtureCleanup = JSON.parse(cp.execFileSync('<PHP_BINARY>', [out + '/fixture.php', 'cleanup'], {encoding: 'utf8'}));
        if (lease) {ps('Release-EasyEduResourceLease.ps1', ['-Resource', 'moodle51-perf', '-RunId', runId]); result.leaseReleased = true;}
        fs.writeFileSync(out + '/native.json', JSON.stringify(result, null, 2));
        console.log(JSON.stringify({passed: result.passed, rows: result.rows.length, errors: result.errors.length, failure: result.failure, restored: result.fixtureCleanup, leaseReleased: result.leaseReleased}));
    }
})();
